import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"أخلاقيات الروحين","description":"","frontmatter":{},"headers":[],"relativePath":"ar/58-双魂伦理准则.md","filePath":"ar/58-双魂伦理准则.md","lastUpdated":1789183869000}'),d={name:"ar/58-双魂伦理准则.md"};function e(o,t,h,n,s,b){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="أخلاقيات-الروحين" tabindex="-1">أخلاقيات الروحين <a class="header-anchor" href="#أخلاقيات-الروحين" aria-label="Permalink to &quot;أخلاقيات الروحين&quot;">​</a></h1><table tabindex="0"><thead><tr><th>البند</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>58</td></tr><tr><td>الوحدة</td><td>الأعراق وأشكال الحياة</td></tr><tr><td>الكلمات المفتاحية</td><td>أخلاقيات الروحين، حقوق الشخصية، كرامة الروح، موازنة المصالح، المراجعة الأخلاقية</td></tr></tbody></table><h2 id="أولاً-طرح-مسألة-أخلاقيات-الروحين" tabindex="-1">أولاً: طرح مسألة أخلاقيات الروحين <a class="header-anchor" href="#أولاً-طرح-مسألة-أخلاقيات-الروحين" aria-label="Permalink to &quot;أولاً: طرح مسألة أخلاقيات الروحين&quot;">​</a></h2><p>مسألة أخلاقيات الروحين هي المسألة الأخلاقية الجوهرية التي يجب على حضارة التكافل المرساة الإجابة عنها عند مواجهة كيانات الاستبدال المظلم (انظر <em>57-黑暗置换体起源与本质</em>). فعندما يوجد في جسد واحد روحان مستقلان — الروح الأصلي المضيف وروح الاستبدال المظلم — تنشأ سلسلة من المسائل الأخلاقية العميقة:</p><ul><li>هل يتمتع الروحان بحقوق شخصية مستقلة؟</li><li>هل حقوق الروح الأصلي المضيف أولى من حقوق روح الاستبدال المظلم؟</li><li>هل إفناء روح الاستبدال المظلم لحماية الروح الأصلي المضيف أخلاقي؟</li><li>عندما تتعارض مصالح الروحين، كيف تُوازن؟</li><li>هل المجتمع ملزم باستثمار الموارد لإنقاذ الأرواح الأصلية المضيفة التي تم استبدالها مظلماً؟</li><li>هل لروح الاستبدال المظلم «حق في البقاء»؟</li></ul><p>لا إجابات بسيطة عن هذه المسائل، بل يجب وضع مبادئ أخلاقية منهجية لتوجيه الممارسة. أخلاقيات الروحين هي بالضبط الوثيقة المعيارية الموضوعة استجابة لهذه المسائل، وهي الأساس الأخلاقي للتعرف على كيانات الاستبدال المظلم وعلاجها ومعالجتها.</p><h2 id="ثانياً-المبادئ-الأساسية-لأخلاقيات-الروحين" tabindex="-1">ثانياً: المبادئ الأساسية لأخلاقيات الروحين <a class="header-anchor" href="#ثانياً-المبادئ-الأساسية-لأخلاقيات-الروحين" aria-label="Permalink to &quot;ثانياً: المبادئ الأساسية لأخلاقيات الروحين&quot;">​</a></h2><p>تقر أخلاقيات الروحين المبادئ الأساسية الستة التالية بوصفها حجر الزاوية القيمي لمعالجة مسائل الروحين:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>مبدأ كرامة الروح</td><td>كل روح ذات وعي مستقل تتمتع بكرامة فطرية، ولا يجوز إفناؤها أو استعبادها عشوائياً</td></tr><tr><td>مبدأ أولوية الروح الأصلي</td><td>في صراعات الروحين، حقوق الروح الأصلي المضيف الشرعية أولى من حقوق روح الاستبدال المظلم، لأن المضيف الأصلي هو المالك الشرعي للجسد</td></tr><tr><td>مبدأ أقل ضرر</td><td>عند معالجة مسائل الروحين، يجب اختيار الحل الأقل ضرراً لجميع الأطراف المعنية، وتجنب إفناء الأرواح قدر الإمكان</td></tr><tr><td>مبدأ التناسب</td><td>يجب أن تتناسب الإجراءات المتخذة مع درجة خطورة كيان الروحين، ويحظر الإفراط في المعالجة</td></tr><tr><td>مبدأ الموافقة المستنيرة</td><td>عندما يستطيع الروح الأصلي المضيف التعبير عن إرادته، يجب الحصول على موافقته على القرارات الكبرى التي تمس جسده وروحه</td></tr><tr><td>مبدأ بذل أقصى جهد للإنقاذ</td><td>المجتمع ملزم ببذل أقصى جهد معقول لإنقاذ الأرواح الأصلية المضيفة التي استُبدلت مظلماً، ولا يجوز التخلي عنها بسهولة</td></tr></tbody></table><h2 id="ثالثاً-تحديد-حقوق-الشخصية-للروحين" tabindex="-1">ثالثاً: تحديد حقوق الشخصية للروحين <a class="header-anchor" href="#ثالثاً-تحديد-حقوق-الشخصية-للروحين" aria-label="Permalink to &quot;ثالثاً: تحديد حقوق الشخصية للروحين&quot;">​</a></h2><p>المسألة الأولى في أخلاقيات الروحين هي تحديد حقوق الشخصية للروحين. تقر هذه الأخلاقيات قواعد التحديد التالية:</p><h3 id="_1-حقوق-شخصية-الروح-الأصلي-المضيف" tabindex="-1">(1) حقوق شخصية الروح الأصلي المضيف <a class="header-anchor" href="#_1-حقوق-شخصية-الروح-الأصلي-المضيف" aria-label="Permalink to &quot;(1) حقوق شخصية الروح الأصلي المضيف&quot;">​</a></h3><p>الروح الأصلي المضيف هو المالك الشرعي للجسد، وحقوقه الشخصية معترف بها ومحمية بالكامل:</p><ol><li>يتمتع الروح الأصلي المضيف بجميع الحقوق الأساسية التي يمنحها دستور التكافل، بما فيها الحق في الحياة والحق في الجسد والحق في الصحة والحق في كرامة الشخصية وغيرها.</li><li>للروح الأصلي المضيف حق القرار النهائي في جسده؛ وعندما يستطيع التعبير عن إرادته، يجب الحصول على موافقته على أي معالجة كبرى تمس الجسد.</li><li>حقوق ومصالح الروح الأصلي المضيف الشرعية، كحقوق الملكية وحقوق الهوية والعلاقات الاجتماعية، محمية بالقانون ولا تزول بسبب الاستبدال المظلم.</li><li>للروح الأصلي المضيف الحق في تلقي الإغاثة والدعم الاجتماعيين، بما فيها علاج التنقية والمساعدة القانونية والإرشاد النفسي وغيرها.</li><li>حتى لو قُمع قمعاً عميقاً، تظل حقوق شخصية الروح الأصلي المضيف قائمة، ولا يجوز إعلان وفاته أو حرمانه من حقوقه.</li></ol><h3 id="_2-حقوق-شخصية-روح-الاستبدال-المظلم" tabindex="-1">(2) حقوق شخصية روح الاستبدال المظلم <a class="header-anchor" href="#_2-حقوق-شخصية-روح-الاستبدال-المظلم" aria-label="Permalink to &quot;(2) حقوق شخصية روح الاستبدال المظلم&quot;">​</a></h3><p>تحديد حقوق شخصية روح الاستبدال المظلم معقد نسبياً، وتتبنى هذه الأخلاقيات موقف «الاعتراف المحدود»:</p><table tabindex="0"><thead><tr><th>مرحلة التطور</th><th>تحديد حقوق الشخصية</th><th>نطاق الحقوق</th></tr></thead><tbody><tr><td>فترة التآكل الطاقي (المرحلة الأولى)</td><td>لا شخصية مستقلة</td><td>لم يتكون روح مستقل بعد، لا حقوق شخصية مستقلة</td></tr><tr><td>فترة تلوث الروح (المرحلة الثانية)</td><td>لا شخصية مستقلة</td><td>ما زال حالة تلوث للروح الأصلي المضيف، لا حقوق شخصية مستقلة</td></tr><tr><td>فترة تكوين الروحين (المرحلة الثالثة)</td><td>حقوق شخصية محدودة</td><td>وعي مستقل أولي، يتمتع بحقوق كرامة الروح الأساسية، لكن لا يتمتع بحق التحكم بالجسد ولا بحقوق المواطنة الكاملة</td></tr><tr><td>فترة الهيمنة المظلمة (المرحلة الرابعة)</td><td>حقوق شخصية محدودة</td><td>وعي مستقل كامل، يتمتع بحقوق كرامة الروح والحق في المعاملة باحترام، لكن لخطورته تخضع حقوقه لقيود ضرورية</td></tr><tr><td>فترة الاستبدال الكامل (المرحلة الخامسة)</td><td>حقوق شخصية كاملة (لكنه وجود عدائي)</td><td>فني المضيف الأصلي، ويصبح الروح المظلم الروح الوحيد للجسد بحقوق شخصية كاملة، لكن لسلوكه العدائي يجوز اتخاذ إجراءات قسرية تشمل الإفناء وفق القانون</td></tr></tbody></table><h3 id="_3-المحتوى-المحدد-للحقوق-الشخصية-المحدودة" tabindex="-1">(3) المحتوى المحدد للحقوق الشخصية المحدودة <a class="header-anchor" href="#_3-المحتوى-المحدد-للحقوق-الشخصية-المحدودة" aria-label="Permalink to &quot;(3) المحتوى المحدد للحقوق الشخصية المحدودة&quot;">​</a></h3><p>تشمل الحقوق الشخصية المحدودة التي يتمتع بها روح الاستبدال المظلم في المرحلتين الثالثة والرابعة:</p><ol><li><strong>حق كرامة الروح</strong>: لا يعامل بإهانة أو إساءة أو تعذيب، ويجب الحفاظ على الاحترام الأساسي حتى في الضبط والمعالجة.</li><li><strong>حق الإفناء بلا ألم</strong>: إذا حُسم أخيراً إفناء روح الاستبدال المظلم، يجب اعتماد طريقة غير مؤلمة وسريعة لتخفيف معاناته.</li><li><strong>حق التعبير</strong>: في ظروف آمنة خاضعة للضبط، يحق لروح الاستبدال المظلم التعبير عن إرادته وموقفه، لكن تعبيره لا قوة إلزامية له قانوناً.</li><li><strong>حق الاستماع</strong>: عند اتخاذ قرارات كبرى تمس روح الاستبدال المظلم، يجب الاستماع لرأيه في نطاق معقول.</li></ol><p>لا يتمتع روح الاستبدال المظلم بالحقوق التالية: حق التحكم بالجسد، وحق حرية الحركة، والحقوق السياسية المدنية، وحق الملكية (ممتلكات المضيف الأصلي تعود للمضيف الأصلي)، وحق التكاثر (لمنع انتشار النسل المظلم).</p><h2 id="رابعاً-قواعد-موازنة-تعارض-مصالح-الروحين" tabindex="-1">رابعاً: قواعد موازنة تعارض مصالح الروحين <a class="header-anchor" href="#رابعاً-قواعد-موازنة-تعارض-مصالح-الروحين" aria-label="Permalink to &quot;رابعاً: قواعد موازنة تعارض مصالح الروحين&quot;">​</a></h2><p>عندما تتعارض مصالح الروح الأصلي المضيف وروح الاستبدال المظلم، تُوازن وفق القواعد التالية:</p><h3 id="_1-أنواع-التعارض-وقواعد-الموازنة" tabindex="-1">(1) أنواع التعارض وقواعد الموازنة <a class="header-anchor" href="#_1-أنواع-التعارض-وقواعد-الموازنة" aria-label="Permalink to &quot;(1) أنواع التعارض وقواعد الموازنة&quot;">​</a></h3><table tabindex="0"><thead><tr><th>نوع التعارض</th><th>قاعدة الموازنة</th></tr></thead><tbody><tr><td>تعارض حقوق البقاء (بقاء أحدهما مشروط بفناء الآخر)</td><td>حق بقاء الروح الأصلي المضيف أولى؛ وعند استحالة التعايش، تُحمى أولاً بقاء المضيف الأصلي</td></tr><tr><td>تعارض حق التحكم بالجسد</td><td>للروح الأصلي المضيف حق التحكم النهائي بالجسد، وحق تحكم الروح المظلم بالجسد مقيد بصرامة</td></tr><tr><td>تعارض حق التعبير</td><td>لتعبير الروح الأصلي المضيف قوة إلزامية قانوناً، وتعبير الروح المظلم مرجعي فقط</td></tr><tr><td>تعارض حقوق الملكية</td><td>الجسد والممتلكات تعود للمضيف الأصلي، ولا حقوق ملكية للروح المظلم</td></tr><tr><td>تعارض حق اختيار العلاج</td><td>للروح الأصلي المضيف الحق في اختيار قبول علاج التنقية أو رفضه، ولا يحق للروح المظلم منعه</td></tr><tr><td>تعارض طريقة المعالجة</td><td>في المعالجات التي تنطوي على إفناء الروح المظلم، لإرادة الروح الأصلي المضيف دور حاسم (لكن يجب أن تخضع لمراجعة أخلاقية)</td></tr></tbody></table><h3 id="_2-احترام-إرادة-المضيف-الأصلي-وتقييدها" tabindex="-1">(2) احترام إرادة المضيف الأصلي وتقييدها <a class="header-anchor" href="#_2-احترام-إرادة-المضيف-الأصلي-وتقييدها" aria-label="Permalink to &quot;(2) احترام إرادة المضيف الأصلي وتقييدها&quot;">​</a></h3><p>عندما يستطيع الروح الأصلي المضيف التعبير عن إرادته، يجب احترام إرادة المضيف الأصلي احتراماً كاملاً، مع الاستثناءات التالية:</p><ol><li>إرادات المضيف الأصلي التي تضر بوضوح بالسلامة العامة أو بالحقوق والمصالح الشرعية للآخرين لا تحظى بالحماية.</li><li>تعبيرات الإرادة غير الحقيقية الصادرة عن المضيف الأصلي تحت تأثير الروح المظلم لا قوة قانونية لها.</li><li>إذا اختار المضيف الأصلي طوعاً الاندماج مع الروح المظلم، يجب إجراء مراجعة أخلاقية صارمة وتقييم مخاطر للتأكد من أن الوجود بعد الاندماج لن يشكل تهديداً للمجتمع.</li><li>إذا اختار المضيف الأصلي طوعاً التخلي عن العلاج وقبول الاستبدال الكامل بالروح المظلم، يجب على المجتمع التدخل والإرشاد، لكن في حال وعي المضيف الأصلي الكامل وتأكيده المتكرر، يجب في النهاية احترام حق المضيف الأصلي في تقرير المصير (هذه منطقة رمادية أخلاقية تحتاج مراجعة كل حالة على حدة).</li></ol><h2 id="خامساً-آلية-المراجعة-الأخلاقية-للروحين" tabindex="-1">خامساً: آلية المراجعة الأخلاقية للروحين <a class="header-anchor" href="#خامساً-آلية-المراجعة-الأخلاقية-للروحين" aria-label="Permalink to &quot;خامساً: آلية المراجعة الأخلاقية للروحين&quot;">​</a></h2><p>لضمان توافق معالجة مسائل الروحين مع المبادئ الأخلاقية، تقيم الدولة آلية مراجعة أخلاقية للروحين:</p><h3 id="_1-لجنة-المراجعة-الأخلاقية" tabindex="-1">(1) لجنة المراجعة الأخلاقية <a class="header-anchor" href="#_1-لجنة-المراجعة-الأخلاقية" aria-label="Permalink to &quot;(1) لجنة المراجعة الأخلاقية&quot;">​</a></h3><ul><li><strong>التكوين</strong>: تضم علماء أخلاقيات وفقهاء وعلماء حياة وزرّاعاً وممثلين عن الأعراق الأجنبية وممثلين عن الجمهور، على ألا يقل الخبراء ذوو الخبرة في بحث أو علاج كيانات الاستبدال المظلم عن الثلث.</li><li><strong>الاختصاص</strong>: مراجعة المسائل الأخلاقية الكبرى المتعلقة بالروحين والفصل فيها، بما فيها قرارات إفناء الروح المظلم، والموافقة على اندماج الروحين، وتحديد نفوذ إرادة المضيف الأصلي.</li><li><strong>الاستقلال</strong>: تمارس لجنة المراجعة الأخلاقية صلاحياتها باستقلال، دون تدخل من الأجهزة الإدارية أو الأفراد.</li><li><strong>الإجراء</strong>: تعتمد المراجعة نظام جلسات الاستماع، وتصدر قراراتها بعد سماع آراء المضيف الأصلي (إن أمكنه التعبير) والفريق العلاجي وأفراد الأسرة والممثلين الاجتماعيين وجميع الأطراف.</li></ul><h3 id="_2-الأمور-التي-يجب-أن-تخضع-للمراجعة-الأخلاقية-إلزامياً" tabindex="-1">(2) الأمور التي يجب أن تخضع للمراجعة الأخلاقية إلزامياً <a class="header-anchor" href="#_2-الأمور-التي-يجب-أن-تخضع-للمراجعة-الأخلاقية-إلزامياً" aria-label="Permalink to &quot;(2) الأمور التي يجب أن تخضع للمراجعة الأخلاقية إلزامياً&quot;">​</a></h3><p>يجب أن تخضع الأمور التالية لمراجعة وموافقة لجنة المراجعة الأخلاقية للروحين قبل تنفيذها:</p><ol><li>تنفيذ معالجة إفناء الروح المظلم لكيانات الاستبدال المظلم في المرحلتين الثالثة والرابعة.</li><li>إجراء عملية اندماج الروحين لكيانات الاستبدال المظلم.</li><li>إجراء عملية فصل الأرواح لكيانات الاستبدال المظلم.</li><li>اتخاذ قرارات معالجة نهائية لكيانات الاستبدال المظلم التي تكون إرادة مضيفها الأصلي التخلي عن العلاج.</li><li>تنفيذ خطط علاج قد تسبب ضرراً للروح الأصلي المضيف.</li><li>إجراء بحوث علمية تتعلق بالروح على كيانات الاستبدال المظلم.</li><li>أمور أخرى تنطوي على مسائل أخلاقية كبرى للروحين.</li></ol><h2 id="سادساً-الحقوق-والواجبات-الاجتماعية-لكيان-الروحين" tabindex="-1">سادساً: الحقوق والواجبات الاجتماعية لكيان الروحين <a class="header-anchor" href="#سادساً-الحقوق-والواجبات-الاجتماعية-لكيان-الروحين" aria-label="Permalink to &quot;سادساً: الحقوق والواجبات الاجتماعية لكيان الروحين&quot;">​</a></h2><h3 id="_1-الحقوق-الاجتماعية" tabindex="-1">(1) الحقوق الاجتماعية <a class="header-anchor" href="#_1-الحقوق-الاجتماعية" aria-label="Permalink to &quot;(1) الحقوق الاجتماعية&quot;">​</a></h3><p>ما دام الروح الأصلي المضيف موجوداً، يتمتع كيان الروحين (كيان الاستبدال المظلم) بالحقوق الاجتماعية التالية:</p><ol><li>الحق في الحصول على ضمانات المعيشة الأساسية والعلاج الطبي.</li><li>الحق في الحصول على المساعدة القانونية والاستشارات الأخلاقية.</li><li>الحق في التواصل مع الأقارب والأصدقاء في ظروف آمنة خاضعة للضبط.</li><li>الحق في تلقي التعليم والمشاركة في الأنشطة الثقافية (داخل مرافق العزل).</li><li>الحق في الاعتراض على قرارات المعالجة وطلب إعادة النظر فيها.</li></ol><h3 id="_2-الواجبات-والقيود-الاجتماعية" tabindex="-1">(2) الواجبات والقيود الاجتماعية <a class="header-anchor" href="#_2-الواجبات-والقيود-الاجتماعية" aria-label="Permalink to &quot;(2) الواجبات والقيود الاجتماعية&quot;">​</a></h3><p>يتحمل كيان الروحين في الوقت نفسه الواجبات والقيود التالية:</p><ol><li>واجب قبول الضبط العزلي والعلاج.</li><li>واجب عدم مهاجمة أو إصابة الكائنات الحية الأخرى (يخضع المخالفون لضبط أكثر صرامة).</li><li>واجب التعاون مع تقييم التعرف والمراقبة.</li><li>تقييد حرية الحركة بصرامة، وعدم مغادرة مرافق العزل قبل الشفاء.</li><li>عدم ممارسة الزراعة أو نشر الطاقة المظلمة أو أي أنشطة قد تفاقم الاستبدال.</li></ol><h2 id="سابعاً-الخلافات-الحدودية-في-أخلاقيات-الروحين" tabindex="-1">سابعاً: الخلافات الحدودية في أخلاقيات الروحين <a class="header-anchor" href="#سابعاً-الخلافات-الحدودية-في-أخلاقيات-الروحين" aria-label="Permalink to &quot;سابعاً: الخلافات الحدودية في أخلاقيات الروحين&quot;">​</a></h2><p>ما تزال هناك بعض الخلافات الحدودية في مجال أخلاقيات الروحين لم يُتوصل فيها إلى إجماع، وتحتاج إلى استكشاف مستمر في الممارسة:</p><ol><li><strong>مسألة «الخطيئة الأصلية» للروح المظلم</strong>: روح الاستبدال المظلم مدمر منذ ولادته، فهل يعني ذلك أنه «شرير» بالفطرة؟ وهل يمكن وجود روح مظلم «خيّر»؟</li><li><strong>الشرعية الأخلاقية لاندماج الأرواح</strong>: الروح الجديد الناتج عن اندماج الروحين ليس هو المضيف الأصلي ولا الروح المظلم، فكيف يُحدد الوضع الأخلاقي لهذا «الوجود الثالث»؟</li><li><strong>حدود استثمار الموارد</strong>: كم يجب أن يستثمر المجتمع من الموارد لإنقاذ الروح الأصلي المضيف داخل كيان الاستبدال المظلم؟ وعندما تكون تكلفة الإنقاذ مرتفعة جداً ونسبة النجاح منخفضة جداً، هل ما زال واجب بذل أقصى جهد قائماً؟</li><li><strong>إمكانية إصلاح الروح المظلم</strong>: هل يمكن عبر التعليم والاستصلاح وتحويل الطاقة وغيرها من الوسائل تحويل الروح المظلم إلى وجود غير مدمر؟ وإذا أمكن، فهل ينبغي منح الروح المظلم المُصلَح حقوق شخصية كاملة؟</li><li><strong>التوازن بين الوقاية والخصوصية</strong>: لمنع نشوء كيانات الاستبدال المظلم، هل يجوز إجراء مراقبة تعرض الكائنات الحية لطاقة الهاوية؟ وهل تنتهك هذه المراقبة خصوصية الأرواح؟</li></ol><p>تستمر مؤسسات أبحاث أخلاقيات الروحين في دراسة هذه الخلافات، وتصدر لجنة المراجعة الأخلاقية قراراتها في الحالات الفردية وفق الظروف المحددة، وستُحدَّث هذه الأخلاقيات باستمرار بالاستنتاجات ذات الصلة.</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>أخلاقيات الروحين تجسيد عميق لأخلاقيات الحياة في حضارة التكافل المرساة. فهي عبر تقرير المبادئ الأساسية ككرامة الروح وأولوية الروح الأصلي وأقل ضرر، وتحديد حدود حقوق الشخصية للروحين، وبناء قواعد موازنة تعارض المصالح وآليات المراجعة الأخلاقية، توفر أساساً أخلاقياً راسخاً لحوكمة كيانات الاستبدال المظلم. الروح الجوهرية لأخلاقيات الروحين هي: حتى في مواجهة أخطر عدو، لا نتخلى عن التمسك بكرامة الحياة؛ وحتى تحت أعنف تهديد أمني، لا نتجاوز الخط الأخلاقي الأدنى. وهذا هو بالضبط العلامة الجوهرية التي تميز الحضارة التكافلية عن الحضارة الافتراسية.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (أصل وجوهر كيانات الاستبدال المظلم)</li><li>59-黑暗置换体四类分支处置 (معالجة الفروع الأربعة لكيانات الاستبدال المظلم)</li><li>48-司法体系与裁决机制 (النظام القضائي وآلية الفصل)</li><li>40-共生宪法总纲 (الملخص العام لدستور التكافل)</li></ul>',50)])])}const _=a(d,[["render",e]]);export{u as __pageData,_ as default};
